import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.gtmkOXzY.js";const p=JSON.parse('{"title":"Air traffic control","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/atc.md","filePath":"ms-flightsim/atc.md","lastUpdated":null}'),n={name:"ms-flightsim/atc.md"};function i(s,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="air-traffic-control" tabindex="-1">Air traffic control <a class="header-anchor" href="#air-traffic-control" aria-label="Permalink to &quot;Air traffic control&quot;">​</a></h1><p>Pilots ask the tower for landing and takeoff clearance and file flight plans, and a player controller at a three-screen tower console approves or denies them.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li>Each airport can have one controller on duty. They control only that airport.</li><li>At an airport with no controller, every request and flight plan is approved automatically.</li><li>An approved landing or takeoff locks the runway for 2 minutes, so two pilots can&#39;t use it at once.</li><li>ATC voice lines play in English, pre-recorded and free to run.</li></ul><p>The whole system is switched with <code>Config.Features.atc</code> and <code>Config.Features.atcDuty</code>.</p><h2 id="for-pilots" tabindex="-1">For pilots <a class="header-anchor" href="#for-pilots" aria-label="Permalink to &quot;For pilots&quot;">​</a></h2><h3 id="open-the-atc-controls" tabindex="-1">Open the ATC controls <a class="header-anchor" href="#open-the-atc-controls" aria-label="Permalink to &quot;Open the ATC controls&quot;">​</a></h3><p>Press <strong>F10</strong> in a plane or helicopter. It shows the mouse cursor so you can click the cockpit panel. Press <strong>F10</strong> again to hide it.</p><ul><li>If F10 does nothing, type <code>/atccursor</code>, or bind the key in <strong>Settings &gt; Key Bindings &gt; FiveM</strong> (&quot;ATC Communications (Toggle Cursor)&quot;).</li><li>F10 only works once the avionics have finished booting.</li></ul><h3 id="request-landing-or-takeoff" tabindex="-1">Request landing or takeoff <a class="header-anchor" href="#request-landing-or-takeoff" aria-label="Permalink to &quot;Request landing or takeoff&quot;">​</a></h3><ol><li>Press <strong>F10</strong>.</li><li>Click <strong>REQ LAND</strong> or <strong>REQ TKOF</strong> on the cockpit panel.</li><li>Pick a runway from the list. Locked runways show who holds them and can&#39;t be picked.</li><li>Wait for the answer. The button shows whether you were cleared or denied, and a message gives the reason for a denial.</li><li>When cleared, the runway is locked for you and the blue alignment markers show your runway.</li><li>Click <strong>CLR RWY</strong> when you are done, so others can use the runway. Otherwise the lock ends after 2 minutes.</li></ol><p>Before a takeoff clearance, you must be within 250 m of the runway centreline. Otherwise the tower answers &quot;Hold short&quot; and tells you to taxi there first.</p><p>There is no separate taxi request.</p><h3 id="runway-locks" tabindex="-1">Runway locks <a class="header-anchor" href="#runway-locks" aria-label="Permalink to &quot;Runway locks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>Config.RunwayCooldown</code></td><td><code>120</code></td><td>Seconds a runway stays locked after a clearance</td></tr><tr><td><code>Config.RunwayConflictClearance</code></td><td><code>75.0</code></td><td>Runways closer than this (metres) lock together, such as Sandy Shores 12/30 and 09/27, which cross</td></tr></tbody></table><p>Players with a job in <code>Config.EmergencyJobs</code> (default <code>police</code>, <code>ambulance</code>, <code>fire</code>) can take a runway that someone else has locked. The other pilot is told.</p><h3 id="file-a-flight-plan" tabindex="-1">File a flight plan <a class="header-anchor" href="#file-a-flight-plan" aria-label="Permalink to &quot;File a flight plan&quot;">​</a></h3><ol><li>Open the pilot tablet (<code>/pilottablet</code>) and go to the <strong>Flight Plan</strong> tab.</li><li>Choose the departure and arrival airports.</li><li>Optionally choose the departure and arrival runways, a callsign and a cruise altitude. Left blank, the callsign is <code>FLT-&lt;your server ID&gt;</code> and the altitude is picked for you.</li><li>Click <strong>Submit to ATC</strong>.</li></ol><ul><li>With a controller on duty at the departure or arrival airport, the plan waits for their approval.</li><li>With no controller there, the plan is approved at once.</li><li>You can only have one open plan. Click <strong>Cancel Plan</strong> before filing a new one.</li><li>A plan expires 1 hour after you file it (<code>Config.ATCDuty.flightPlanExpiry = 3600</code>).</li><li>Closed airports can&#39;t be used in a plan.</li><li>With a filed plan, landing and takeoff clearance are requested for you as you approach and depart, using the plan&#39;s runways.</li></ul><h3 id="pay-without-clearance" tabindex="-1">Pay without clearance <a class="header-anchor" href="#pay-without-clearance" aria-label="Permalink to &quot;Pay without clearance&quot;">​</a></h3><p>Jobs flown without an approved flight plan pay less while a controller is on duty.</p><table tabindex="0"><thead><tr><th>Config key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Config.Payouts.noATCClearancePayMult</code></td><td><code>0.5</code></td><td>Pay multiplier for a job flown without an approved plan. <code>1.0</code> turns the penalty off.</td></tr><tr><td><code>Config.ATCDuty.freeFlightNoATC</code></td><td><code>true</code></td><td>With no controller on duty, plans are auto-approved and the penalty never applies</td></tr></tbody></table><p><code>Config.Payouts.noATCClearancePayMult</code> overrides <code>Config.ATCDuty.noClearancePayMult</code>, so change it in <code>Config.Payouts</code>. Only an approved flight plan counts. A landing or takeoff clearance on its own does not.</p><h3 id="traffic-on-your-radar" tabindex="-1">Traffic on your radar <a class="header-anchor" href="#traffic-on-your-radar" aria-label="Permalink to &quot;Traffic on your radar&quot;">​</a></h3><p>With <code>Config.ATCScope.pilotsSeeTraffic = false</code> (the default), pilots&#39; radars show the map, nav fixes, flight-plan routes and their own route, but not other aircraft. The controller sees all traffic. TCAS is not affected and still shows nearby aircraft. Set it to <code>true</code> to show traffic to everyone.</p><h2 id="for-controllers" tabindex="-1">For controllers <a class="header-anchor" href="#for-controllers" aria-label="Permalink to &quot;For controllers&quot;">​</a></h2><h3 id="who-can-go-on-duty" tabindex="-1">Who can go on duty <a class="header-anchor" href="#who-can-go-on-duty" aria-label="Permalink to &quot;Who can go on duty&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>Config.ATCDuty.atcJob</code></td><td><code>&#39;pilot&#39;</code></td></tr><tr><td><code>Config.ATCDuty.atcMinGrade</code></td><td><code>2</code></td></tr></tbody></table><p>With open access on (<code>Config.PilotAuthorization.enabled = false</code>), only admins can go on duty.</p><h3 id="go-on-duty" tabindex="-1">Go on duty <a class="header-anchor" href="#go-on-duty" aria-label="Permalink to &quot;Go on duty&quot;">​</a></h3><ol><li>Walk up to a tower console. The prompt reads &quot;[E] Operate radar console&quot;.</li><li>Press <strong>E</strong> to sit at the screens. The key can be rebound in <strong>Settings &gt; Key Bindings &gt; FiveM</strong> (&quot;ATC console: sit at the screens&quot;).</li><li>Click <strong>SIGN ON</strong> at the top of the right screen.</li></ol><p>You now control the airport the console stands in.</p><ul><li>If another player already controls that airport, you can&#39;t sign on there.</li><li>Leave the airport and you get a warning. After 15 seconds outside you are signed off (<code>outsideAirportGraceSeconds</code>).</li><li>Disconnecting signs you off.</li><li>Click <strong>SIGN OFF</strong> to end your shift.</li></ul><h3 id="using-the-console" tabindex="-1">Using the console <a class="header-anchor" href="#using-the-console" aria-label="Permalink to &quot;Using the console&quot;">​</a></h3><ul><li>Move the mouse to point, click to use buttons and menus, and scroll to zoom.</li><li><strong>W</strong>: main screen. <strong>A</strong>: left screen. <strong>D</strong>: right screen. <strong>S</strong>: step back to see all three. Pressing A or D again returns to the main screen.</li><li><strong>Backspace</strong>: leave the console.</li></ul><table tabindex="0"><thead><tr><th>Screen</th><th>What it shows</th></tr></thead><tbody><tr><td>Main</td><td>The radar: runways, range rings, aircraft with callsign, altitude, speed and type, track lines and history dots. Conflicts show yellow, critical ones flashing red. The MAP menu toggles layers such as taxiways, stands, fixes and zones.</td></tr><tr><td>Left</td><td>Aircraft list: callsign, type, altitude, speed, heading, flight-plan status and route. Click a column to sort, click a row to centre the radar on it. AI aircraft are marked AI.</td></tr><tr><td>Right</td><td>Clearance requests, pending flight plans, plans on file, active runways, and sign on / off</td></tr></tbody></table><p>Display defaults are in <code>Config.ATCScope.display</code>: range 10 NM, range menu 0.5 to 40 NM.</p><h3 id="clearances-and-flight-plans" tabindex="-1">Clearances and flight plans <a class="header-anchor" href="#clearances-and-flight-plans" aria-label="Permalink to &quot;Clearances and flight plans&quot;">​</a></h3><p>On the right screen:</p><ul><li><strong>CLEAR</strong> grants a landing or takeoff request. <strong>DENY</strong> asks for a reason: HOLD POSITION, TRAFFIC, WEATHER, RUNWAY CLOSED or RESUBMIT.</li><li><strong>APPROVE</strong> or <strong>DENY</strong> a pending flight plan the same way.</li><li>You only see requests and plans for your airport. Requests from AI aircraft appear here too.</li><li>A chime plays when a new request or plan arrives (<code>Config.ATCScope.sound</code>).</li></ul><h3 id="active-runways" tabindex="-1">Active runways <a class="header-anchor" href="#active-runways" aria-label="Permalink to &quot;Active runways&quot;">​</a></h3><p>Tick up to 2 runways (<code>Config.ATCDuty.maxActiveRunways</code>) under <strong>ACTIVE RUNWAYS</strong> and click <strong>APPLY</strong>. Pilots at your airport see them as the runways in use.</p><h3 id="who-sees-the-screens" tabindex="-1">Who sees the screens <a class="header-anchor" href="#who-sees-the-screens" aria-label="Permalink to &quot;Who sees the screens&quot;">​</a></h3><p>With <code>viewers = &#39;nearby&#39;</code> (default), anyone within 30 m (<code>renderDistance</code>) sees the screens. Set <code>viewers = &#39;atc&#39;</code> so only the on-duty controller&#39;s game draws them.</p><h2 id="placing-the-tower-console-admins" tabindex="-1">Placing the tower console (admins) <a class="header-anchor" href="#placing-the-tower-console-admins" aria-label="Permalink to &quot;Placing the tower console (admins)&quot;">​</a></h2><p>A console is three TV screens. Each console belongs to the airport it stands in. A console outside every airport can&#39;t be used to sign on.</p><h3 id="with-a-command" tabindex="-1">With a command <a class="header-anchor" href="#with-a-command" aria-label="Permalink to &quot;With a command&quot;">​</a></h3><ol><li>Stand where the main screen should go.</li><li>Type <code>/atcscope place</code>. A see-through screen appears. The left and right screens are added beside it automatically.</li><li>Move it into place: <ul><li>Arrow keys: move</li><li><strong>PgUp / PgDn</strong>: raise and lower</li><li><strong>Q / E</strong>: rotate</li><li>Hold <strong>Shift</strong>: small steps</li></ul></li><li>Press <strong>Enter</strong> to save, or <strong>Backspace</strong> to cancel.</li></ol><p><code>/atcscope place left</code> or <code>/atcscope place right</code> moves one side screen yourself. <code>/atcscope swap</code> mirrors the sides if they come out the wrong way round. <code>/atcscope remove</code> deletes the nearest console. These commands are admin-only.</p><h3 id="with-the-admin-panel" tabindex="-1">With the admin panel <a class="header-anchor" href="#with-the-admin-panel" aria-label="Permalink to &quot;With the admin panel&quot;">​</a></h3><p>Open <code>/adminps</code> &gt; <strong>Screens</strong> and click <strong>Place ATC Console</strong>. The same placement tool starts. The list shows every console with its airport and position, with <strong>Go To</strong>, <strong>Move</strong> and <strong>Remove</strong> (press Remove twice to confirm).</p><p>Placed consoles are saved in the database. They survive restarts and script updates.</p><p>Consoles can also be written by hand in <code>Config.ATCScope.stations</code>. An airport with a console in <code>config.lua</code> uses only that one.</p><h2 id="atc-voice" tabindex="-1">ATC voice <a class="header-anchor" href="#atc-voice" aria-label="Permalink to &quot;ATC voice&quot;">​</a></h2><p>The tower speaks: flight plan received, clearance granted or denied, runway assignment and waypoint callouts.</p><ul><li>The voice ships pre-recorded in English in <code>html/sounds/atc/cache</code>. Upload the whole folder.</li><li><code>Config.AIATCChatter.runtimeMode = &#39;static&#39;</code> (default) plays only the shipped recordings. No API key, no cost.</li><li>Each airport has its own voice: LSIA a New York accent, Sandy Shores and Grapeseed a Southern accent, Cayo Perico a Spanish accent.</li><li>Turn single kinds of lines off in <code>Config.AIATCChatter.triggers</code>.</li><li><code>Config.AIATCChatter.enabled = false</code> silences all ATC speech. The F10 menu, clearances and runway locks still work. Cockpit callouts are separate (<code>Config.Features.sounds</code>).</li></ul><h3 id="re-recording-the-voice-optional" tabindex="-1">Re-recording the voice (optional) <a class="header-anchor" href="#re-recording-the-voice-optional" aria-label="Permalink to &quot;Re-recording the voice (optional)&quot;">​</a></h3><p>You only need this to make your own voice or phrases. It uses ElevenLabs and costs you API credit.</p><ol><li><p>Add your key to <code>server.cfg</code> as a convar. Use <code>set</code>, never <code>setr</code>; the key never reaches players.</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">set ms_flightsim_elevenlabs_key </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-key&quot;</span></span></code></pre></div></li><li><p>Choose your voices in <code>Config.AIATCChatter.elevenlabs</code>.</p></li><li><p>Restart the server.</p></li><li><p>Run <code>/atcbootstrap</code> from the server console, or in game as an admin. It records the ATC phrase library and skips lines already recorded.</p></li><li><p>Run <code>/atchudbootstrap</code> to re-record the cockpit callouts too. It replaces the files in <code>html/sounds</code>.</p></li></ol><p>To record missing lines on the fly while players fly, set <code>runtimeMode = &#39;runtime&#39;</code>. Daily limits stop runaway costs: <code>dailyCharCap = 50000</code> characters for the server and <code>perPilotDailyChars = 2500</code> per pilot. Without the key, runtime mode switches the voice off instead of erroring.</p>',60)])])}const g=o(n,[["render",i]]);export{p as __pageData,g as default};
